-- Single-UUID review. Preserve manual edits, ownership, media and workout history.
BEGIN;
SELECT id FROM "Exercise" WHERE id='7bd5b49f-252c-43a2-83a8-816d6401f6cb' FOR UPDATE;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM "Exercise" WHERE id='7bd5b49f-252c-43a2-83a8-816d6401f6cb' AND ("ownerUserId" IS NOT NULL OR name <> 'Agachamento Hack na Máquina')) THEN
  RAISE EXCEPTION 'Hack squat identity changed; review manually';
 END IF;
 IF EXISTS (SELECT 1 FROM "Exercise" e WHERE e.id='7bd5b49f-252c-43a2-83a8-816d6401f6cb' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL AND (
  NOT EXISTS (SELECT 1 FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND m."muscleGroup"='QUADRICEPS' AND m.role='PRIMARY') OR
  NOT EXISTS (SELECT 1 FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND m."muscleGroup"='GLUTES' AND m.role='PRIMARY') OR
  NOT EXISTS (SELECT 1 FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND m."muscleGroup"='ADDUCTORS' AND m.role='SECONDARY') OR
  EXISTS (SELECT 1 FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND NOT ((m."muscleGroup" IN ('QUADRICEPS','GLUTES') AND m.role='PRIMARY') OR (m."muscleGroup" IN ('ADDUCTORS','CORE','BACK') AND m.role='SECONDARY')))
 )) THEN RAISE EXCEPTION 'Hack squat classification changed; review manually'; END IF;
END $$;
INSERT INTO "ExerciseMuscle" (id,"exerciseId","muscleGroup",role,"createdAt")
SELECT gen_random_uuid()::text,e.id,g::"MuscleGroup",'SECONDARY',CURRENT_TIMESTAMP FROM "Exercise" e CROSS JOIN (VALUES ('CORE'),('BACK')) groups(g)
WHERE e.id='7bd5b49f-252c-43a2-83a8-816d6401f6cb' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL ON CONFLICT ("exerciseId","muscleGroup") DO NOTHING;
UPDATE "Exercise" e SET "anatomyReview"='{"version":"2026-10-30.1","reviewedAt":"2026-10-30T17:00:00.000Z","variant":"Agachamento Hack bilateral em trenó inclinado a 45°, costas apoiadas, ombros sob almofadas e pés fixos em plataforma a 20°; joelhos aproximadamente entre 17° e 99° de flexão.","aliases":["agachamento hack","agachamento hack na máquina","hack squat","hack squat machine"],"participants":[{"id":"RECTUS_FEMORIS","label":"Reto femoral","muscleGroup":"QUADRICEPS","role":"PRIMARY","aliases":["quadríceps","quadriceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"VASTUS_LATERALIS","label":"Vasto lateral","muscleGroup":"QUADRICEPS","role":"PRIMARY","aliases":["quadríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"VASTUS_MEDIALIS","label":"Vasto medial","muscleGroup":"QUADRICEPS","role":"PRIMARY","aliases":["quadríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"VASTUS_INTERMEDIUS","label":"Vasto intermédio","muscleGroup":"QUADRICEPS","role":"PRIMARY","aliases":["vasto intermediário","quadríceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"GLUTEUS_MAXIMUS","label":"Glúteo máximo","muscleGroup":"GLUTES","role":"PRIMARY","aliases":["glúteos","gluteus maximus"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"ADDUCTOR_MAGNUS","label":"Adutor magno","muscleGroup":"ADDUCTORS","role":"SECONDARY","aliases":["grande adutor","adductor magnus","adutores"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["ARNOLD_2010"]},{"id":"RECTUS_ABDOMINIS","label":"Reto abdominal","muscleGroup":"CORE","role":"SECONDARY","aliases":["abdômen","abdominais","rectus abdominis"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["CLARK_2019"]},{"id":"EXTERNAL_OBLIQUE","label":"Oblíquo externo","muscleGroup":"CORE","role":"SECONDARY","aliases":["oblíquos","external oblique","abdômen"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["CLARK_2019"]},{"id":"ERECTOR_SPINAE","label":"Eretores da coluna","muscleGroup":"BACK","role":"SECONDARY","aliases":["eretor da espinha","eretores espinhais","lombar","erector spinae"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["CLARK_2019"]}],"sources":[{"id":"CLARK_2019","title":"Clark, Lambert e Hunter — Trunk Muscle Activation in the Back and Hack Squat at the Same Relative Loads (2019)","url":"https://doi.org/10.1519/JSC.0000000000002144","limitation":"Dez homens, máquina Hack apoiada versus agachamento com barra, EMG de reto abdominal, oblíquo externo e eretores lombares em quatro cargas relativas. Fundamenta estabilizadores; não mediu músculos das pernas nem estabelece ângulo ideal, hipertrofia ou segurança individual. Individualizar componentes do grupo eretor na malha é inferência anatômica, sem EMG separado de cada estrutura."},{"id":"ARNOLD_2010","title":"Arnold et al. — A Model of the Lower Limb for Analysis of Human Movement (2010)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2903973/","limitation":"Modelo musculoesquelético de membros inferiores, não ensaio de Hack. Extensores do joelho/quadril e auxílio do adutor magno fundamentam a classificação anatômica editorial; não se inferem magnitudes de EMG, igualdade de esforço entre os vastos ou ênfase regional."}],"notes":"Quadríceps e glúteo máximo principais na extensão de joelhos/quadris; adutor magno auxilia a extensão do quadril. Reto abdominal, oblíquo externo e eretores da coluna estabilizam o tronco mesmo com encosto. Os componentes superficiais lombares/torácicos do grupo eretor são ilustrados conjuntamente; a fonte não mediu cada um separadamente. Nenhuma ênfase regional ou isolamento por posição dos pés é afirmado. Isquiotibiais, panturrilhas e outros músculos podem coestabilizar: mapa ilustrativo não exaustivo, cor neutra não significa inatividade. Não transferir resultados do Hack com barra atrás do corpo para esta máquina. Inclinação, plataforma, amplitude e cadência são escolhas ilustrativas, sem superioridade universal, medição de EMG ou intensidade real.","instructions":{"description":"Agachamento bilateral na máquina Hack com costas apoiadas e trenó guiado inclinado.","setup":"Ajuste as travas e a carga. Apoie as costas no encosto, os ombros sob as almofadas e os pés inteiros na plataforma, aproximadamente à largura dos ombros. Segure as alças e libere o trenó conforme o equipamento.","execution":"Desça de forma controlada flexionando joelhos e quadris, mantendo os pés apoiados e os joelhos na direção dos pés. Faça uma pausa breve na amplitude confortável e empurre a plataforma para subir suavemente, sem travar os joelhos.","tips":"Mantenha o tronco estável no encosto e acione as travas ao terminar. A ilustração usa trilhos a 45° e cerca de 17° a 99° de flexão dos joelhos; ajuste a amplitude ao equipamento e à orientação individual. As cores indicam participação muscular ilustrativa, sem medição de EMG ou intensidade real de esforço."}}'::jsonb,"updatedAt"=CURRENT_TIMESTAMP WHERE e.id='7bd5b49f-252c-43a2-83a8-816d6401f6cb' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL;
COMMIT;
